concepts.ex:
$servers = Get-Content .\servers.txt

# port check, output as objects -> CSV
$servers | ForEach-Object {
  [pscustomobject]@{
    Server = $_
    Https  = (Test-NetConnection $_ -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded
  }
} | Export-Csv .\port-report.csv -NoTypeInformation

# run on many servers in parallel over WinRM
Invoke-Command -ComputerName $servers -ScriptBlock {
  Get-Volume -DriveLetter C | Select-Object @{n='FreeGB';e={[math]::Round($_.SizeRemaining/1GB,1)}}
} | Select-Object PSComputerName, FreeGB

# stopped automatic services
Get-CimInstance Win32_Service -Filter "StartMode='Auto' AND State<>'Running'" |
  Select-Object Name, State

upstream app {
    server 10.2.0.11:8080;
    server 10.2.0.12:8080;
}
server {
    listen 443 ssl;
    server_name app.example.com;
    ssl_certificate     /etc/nginx/certs/app.crt;
    ssl_certificate_key /etc/nginx/certs/app.key;
    location / {
        proxy_pass http://app;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}

nginx -t && systemctl reload nginx

pipeline {
  agent any
  stages {
    stage('Build')  { steps { sh 'mvn -q package' } }
    stage('Test')   { steps { sh 'mvn -q test' } }
    stage('Deploy') {
      steps { sh './deploy.sh qa' }
    }
  }
}
